const path = require("node:path");
const {
  createContractProgram,
  renderTypeAliases,
  writeOrCheckContract,
  checkContractDeclarations,
} = require("./contract-generation.cjs");

const source = path.resolve(__dirname, "../src/lib/catalog-permission/contracts.ts");
const target = path.resolve(__dirname, "../.mercur/catalog-permission-contracts.d.ts");
const program = createContractProgram([source], { skipLibCheck: false });
const result =
  "// Generated by scripts/generate-catalog-permission-contracts.cjs. Do not edit.\n" +
  renderTypeAliases(program, [source]) +
  "\n";

if (
  writeOrCheckContract(
    target,
    result,
    "Catalog permission contracts are stale; run pnpm catalog:contracts:generate",
  )
) {
  checkContractDeclarations(
    [target],
    "Catalog permission contract declaration failed typechecking",
  );
}
